SELECT s.* FROM shopping_session s
WHERE s.state IN
#{__item}
AND s.updated_at >= #{since}
ORDER BY s.updated_at ASC
LIMIT #{limit}

SELECT COUNT(*) FROM shopping_session
WHERE created_at >= #{start} AND created_at < #{end}
AND state IN
#{st}

SELECT COUNT(*) FROM shopping_session
WHERE created_at > #{since}
AND state IN
#{st}

SELECT COUNT(*) FROM shopping_session
WHERE created_at > #{since}
AND state IN
#{st}
AND device_id IN
#{id}

SELECT CAST(COALESCE(AVG(EXTRACT(EPOCH FROM (close_time - open_time)) * 1000), 0) AS BIGINT)
FROM shopping_session
WHERE created_at > #{since}
  AND open_time IS NOT NULL AND close_time IS NOT NULL
  AND device_id IN
#{id}
